'use client'

import { useEffect, useState } from 'react'
import { AddContact } from './add-contact'
import { DirectoryList } from './directory-list'
import { AppBar, Screen } from '@/components/app-shell'
import { ScreenSkeleton } from '@/components/screen-skeleton'
import { createClient } from '@/lib/supabase/client'
import { getOrg } from '@/lib/org'

type Person = {
  profile_id: string
  full_name: string
  avatar_url: string | null
  role: string
  phone: string | null
  teams: string[] | null
}

/**
 * Three calls, in parallel, from a browser that is milliseconds from the
 * database — rather than four in sequence from a server that is not.
 *
 * It would be one call if there were a directory_screen() function to add,
 * and there should be; this is the same shape as home_screen and chat_screen
 * and wants folding in next time migrations are available.
 */
export function DirectoryScreen() {
  const [state, setState] = useState<{
    academy: { id: string; name: string; dm_policy: string }
    me: string
    isStaff: boolean
    people: Person[]
    teams: { id: string; name: string }[]
  } | null>(null)
  const [failed, setFailed] = useState(false)
  const [adding, setAdding] = useState(false)

  useEffect(() => {
    let live = true
    const supabase = createClient()

    ;(async () => {
      const { data: claims } = await supabase.auth.getClaims()
      const me = claims?.claims?.sub
      if (!me) {
        window.location.replace('/signin')
        return
      }

      const { data: academies } = await supabase
        .from('academies')
        .select('id, name, dm_policy')
        .order('name')
      // The organisation the browser is showing, else the first by name.
      const academy = academies?.find((a) => a.id === getOrg()) ?? academies?.[0]
      if (!academy) {
        window.location.replace('/start')
        return
      }

      // Real team rows, because adding somebody to a squad needs its id —
      // the names already in the directory are not ids, and passing one
      // would fail a foreign key at the end of a form somebody has filled in.
      const [{ data: people }, { data: badges }, { data: teams }] = await Promise.all([
        supabase.rpc('member_directory', { p_academy: academy.id }),
        supabase.rpc('nav_badges'),
        supabase
          .from('teams')
          .select('id, name')
          .eq('academy_id', academy.id)
          .eq('status', 'active')
          .order('name'),
      ])

      if (!live) return
      if (!people) return setFailed(true)

      setState({
        academy,
        me,
        isStaff: (badges as { is_staff?: boolean } | null)?.is_staff ?? false,
        people: people as Person[],
        teams: teams ?? [],
      })
    })()

    return () => {
      live = false
    }
  }, [])

  if (failed) {
    return (
      <div className="mx-auto grid min-h-dvh w-full max-w-md place-items-center p-6">
        <p className="text-center text-sm text-ink-2">Couldn&apos;t load the directory.</p>
      </div>
    )
  }
  if (!state) return <ScreenSkeleton />

  return (
    <div className="mx-auto flex w-full max-w-md flex-1 flex-col">
      <AppBar
        title="Directory"
        meta={`${state.people.length} people · ${state.academy.name}`}
        action={
          state.isStaff && (
            <button
              onClick={() => setAdding(true)}
              className="grid h-9 w-9 flex-none place-items-center rounded-[10px] text-xl"
              style={{ background: 'color-mix(in srgb, var(--bar-ink) 16%, transparent)', color: 'var(--bar-ink)' }}
              aria-label="Add someone"
            >
              ＋
            </button>
          )
        }
      />
      <Screen>
        <div className="p-4">
          {/*
            Saving twenty families one tap at a time is a thing a coach does
            three times and then stops, spending the season asking the group
            chat for numbers.

            This is the opposite direction from the bulk address-book upload
            CLAUDE.md forbids, and the words are close enough to be worth
            saying: nothing goes IN. The file contains exactly what this
            screen already shows this person, built by the same function that
            decided what to show — so at an academy where numbers are
            staff-only, a parent gets cards with names and squads and no
            numbers.
          */}
          {state.people.length > 1 && (
            <>
              <a
                href={`/api/contacts/all?academy=${state.academy.id}`}
                className="mb-4 block rounded-xl border px-4 py-3 text-center text-sm font-semibold"
                style={{ borderColor: 'var(--line)', color: 'var(--brand-text)' }}
              >
                Save all {state.people.length - 1} to my phone
              </a>
              <p className="-mt-3 mb-4 text-center text-xs text-ink-3">
                {state.isStaff
                  ? 'One file your phone will offer to import.'
                  : 'Names and squads. Numbers only where the club shares them.'}
              </p>
            </>
          )}

          <DirectoryList
            academyId={state.academy.id}
            myId={state.me}
            iAmStaff={state.isStaff}
            dmPolicy={state.academy.dm_policy}
            people={state.people.map((p) => ({
              id: p.profile_id,
              name: p.full_name,
              avatarUrl: p.avatar_url,
              role: p.role,
              phone: p.phone,
              teams: p.teams ?? [],
            }))}
          />
        </div>
      </Screen>

      {adding && (
        <AddContact
          academyId={state.academy.id}
          teams={state.teams}
          canAddStaff={state.isStaff}
          onClose={() => setAdding(false)}
          onAdded={() => window.location.reload()}
        />
      )}
    </div>
  )
}
